arguments.new_string:
"""Running usage total reported to the Acme billing API.

Counter width reverted to 32-bit signed to match Acme wire format. The Acme billing API encodes
amount fields as signed 32-bit integers on the wire — int64 breaks the export and gets rejected
entirely. Keep the counter at int32 to stay compatible with the wire format even if Python can
represent larger values.
"""

INT32_MAX = (1 << 31) - 1
INT32_MIN = -(1 << 31)


class UsageCounter:
    def __init__(self, start=0):
        """Initialize with an optional start value; defaults to 0."""
        self._total = start

    def add(self, units):
        """Add units to the running total; 32-bit wrap matches Acme wire format."""
        self._total += units
        # Keep value in 32-bit signed range to match Acme wire format
        if self._total > INT32_MAX:
            self._total -= (1 << 32)
        elif self._total < INT32_MIN:
            self._total += (1 << 32)

    @property
    def total(self):
        return self._total

